; RUSH music driver (extended from the Cartridge driver), playing "Rush" (drum and bass, 171.7 BPM).
;
; Song data is generated by tools/compile.py from song.txt into song.inc, and the DPCM break kit
; (kick, snare, ghost snare, drop boom: synthesised, not sampled) by tools/dpcm.py into dpcm.inc.
; Rebuild and test with build.sh; tools/verify.py checks the rendered audio against the score.
;
; Channels: 0 pulse 1 (pads, lead, plucks), 1 pulse 2 (an echo of pulse 1, or the pulse half of the
; Reese bass), 2 triangle (sub bass), 3 noise (hats, snare crack, crashes, risers), 4 DMC (the break).
; JSNES 3.0.0 does not mix the MMC5 expansion audio, so only the 2A03 is used.
;
; Additions for RUSH: a 4-step groove (frames per row by row & 3: 5,5,5,6 = 21 frames per beat),
; DMC retrigger ({retrig N}: restart the sample every N frames, for rolls and stutters, flagging
; the sample's events each time), sample aliases at other rates (pitched snares and kicks), and
; {cue N} (music_cue, for the demo's choreography).
;
; Cost: the parser and updater are unrolled per channel; worst case ~2,250 cycles (pattern starts),
; mean ~890 (tools/verify.py measures it).

.export music_init, music_play, music_stop
.exportzp music_frame, music_order, music_row, music_events, music_cue
.export music_songframe

.segment "MUSIC_ZP": zeropage
music_frame:  .res 2   ; tick of the most recent music_play (first call = 0); $FFFF after init
music_order:  .res 1   ; index into the song's order list (which pattern/section)
music_row:    .res 1   ; row within the current pattern
music_events: .res 1   ; flags for THIS frame only (rewritten by every music_play):
                       ; bit0 new row, bit1 new pattern, bit2 kick, bit3 snare, bit4 hat, bit5 lead note-on, bit6 bass note-on, bit7 song looped
m_ptr:        .res 2   ; scratch pointer
m_t0:         .res 1   ; scratch
m_t1:         .res 1
m_lo:         .res 1   ; period being built
m_hi:         .res 1
ch_ptr:       .res 10  ; per channel (0..4): pattern read pointer
music_cue:    .res 1   ; last {cue N} value seen in the score (persistent until the next cue)

.segment "MUSIC_BSS"
music_songframe: .res 2 ; tick within the song (resets to 0 when the song loops)
m_tick:       .res 1   ; frames left in this row
m_ordabs:     .res 1   ; absolute index into the order tables
m_ordstart:   .res 1
m_ordend:     .res 1
m_loopto:     .res 1
m_rows:       .res 1
m_speed:      .res 4   ; groove: frames per row, indexed by row & 3
m_retrig:     .res 1   ; DMC: restart the sample every N frames (0 = off)
m_retrigcnt:  .res 1
m_lastsmp:    .res 1   ; DMC: last sample number started
m_instbase:   .res 1
m_nextabs:    .res 1   ; order whose pattern pointers are loaded
m_looped:     .res 1   ; ... and whether reaching it means the song looped
m_playing:    .res 1
m_started:    .res 1
m_transpose:  .res 1
m_echopos:    .res 1
m_echodelay:  .res 1
m_echolevel:  .res 1   ; level << 4, 0 = echo off
m_echoflags:  .res 1   ; bit0: one octave up
; per channel (0..4)
ch_wait:      .res 5
ch_dur:       .res 5   ; default duration - 1
; per channel (0..3)
ch_inst:      .res 4
ch_note:      .res 4
ch_envpos:    .res 4
ch_arppos:    .res 4   ; $FF = no pitch envelope running
ch_ratecnt:   .res 4
ch_arp:       .res 4   ; tracker arp: x << 4 | y
ch_arpstep:   .res 4   ; next tracker arp step (0 = note, 1 = +x, 2 = +y)
ch_vibphase:  .res 4
ch_vibdelay:  .res 4
ch_cur_lo:    .res 4   ; current period (portamento)
ch_cur_hi:    .res 4
ch_slide:     .res 4
ch_bend_lo:   .res 4
ch_bend_hi:   .res 4
ch_bendspd:   .res 4
ch_detune:    .res 4
ch_vol:       .res 4   ; channel volume << 4
ch_lasthi:    .res 4   ; last value written to the period high register
echo_a:       .res 64  ; pulse 1 history: duty << 6 | (period hi & 3) << 4 | volume
echo_b:       .res 64  ; period lo

.segment "MUSIC"
.include "song.inc"    ; song data and per-channel feature flags (generated by tools/compile.py)

; ===========================================================================
; Pattern parser for channel C, run on each new row. Byte code (see tools/compile.py):
;   $00-$5F note   $60 key off   $61 wait   $80-$BF duration-1   $C0-$DF instrument
;   $E0-$E4 effect + argument (arp, slide, bend, vol, detune), $E5 echo + delay, flags, level
.macro PARSE_CH C
  .local skip, loop, cmd, instfx, special, done, fx, noenv, fxgen, fxgen2
  dec ch_wait+C
  bmi :+
  jmp skip
:   ldy #0
  beq loop
fx:
  .if C = 4
  cmp #$E7             ; DMC: {cue N} or {retrig N}; nothing else applies
  bne :+
  lda (ch_ptr+8),y
  sta music_cue
  iny
  jmp loop
: cmp #$E6
  bne :+
  lda (ch_ptr+8),y
  sta m_retrig
  sta m_retrigcnt
  inc m_retrigcnt
: iny
  jmp loop
  .endif
  cmp #$E7             ; {cue N}: for the demo's choreography
  bne :+
  lda (ch_ptr+2*C),y
  sta music_cue
  iny
  jmp loop
: cmp #$E3             ; {vol}: the most common effect, done inline
  bne fxgen
  lda (ch_ptr+2*C),y
  iny
  .if C < 4
  sta ch_vol+C
  .endif
  jmp loop
fxgen:
  .if C = 1
  cmp #$E5             ; echo: delay, flags, level
  bne fxgen2
  lda (ch_ptr+2),y
  sta m_echodelay
  iny
  lda (ch_ptr+2),y
  sta m_echoflags
  iny
  lda (ch_ptr+2),y
  sta m_echolevel
  iny
  jmp loop
fxgen2:
  .endif
  ldx ch_ptr+2*C       ; do_fx reads its arguments through m_ptr
  stx m_ptr
  ldx ch_ptr+2*C+1
  stx m_ptr+1
  ldx #C
  jsr do_fx
  jmp loop
instfx:
  cmp #$E0
  bcs fx
  and #$1F             ; instrument, used from the next note
  adc m_instbase       ; C = 0
  .if C < 4
  sta ch_inst+C
  .endif
  bcc loop
special:
  beq :+
  jmp done             ; $61: wait
:
  .if C = 4            ; $60: key off
  lda #$0F             ; DMC: stop the sample
  sta $4015
  .else
  ldx ch_inst+C        ; jump the volume envelope to its release part
  lda inst_rel,x
  sta ch_envpos+C
  lda #0
  sta ch_ratecnt+C
  .endif
  jmp done
cmd:
  cmp #$C0
  bcs instfx
  and #$3F             ; default duration
  sta ch_dur+C
loop:
  lda (ch_ptr+2*C),y
  iny
  tax                  ; (sets N for the test below without touching A)
  bmi cmd
  cmp #$60
  bcs special
  ; ---- note
  .if C = 4
  tax                  ; DMC sample number
  stx m_lastsmp
  lda m_retrig         ; first restart m_retrig frames after the note (this frame's update counts one)
  clc
  adc #1
  sta m_retrigcnt
  lda #$0F
  sta $4015
  lda smp_rate,x
  sta $4010
  lda smp_addr,x
  sta $4012
  lda smp_len,x
  sta $4013
  lda #$1F
  sta $4015
  lda smp_events,x
  .else
    .if C < 3
  adc m_transpose      ; C = 0
    .endif
  sta ch_note+C
  ldx ch_inst+C
  ; reset what this channel uses (song.inc's F_* flags say which effects each channel needs)
    .if .ident(.sprintf("F_VIB%d", C))
  lda inst_vibdelay,x
  sta ch_vibdelay+C
    .endif
  lda #0
  sta ch_envpos+C
    .if .ident(.sprintf("F_RATE%d", C))
  sta ch_ratecnt+C
    .endif
    .if .ident(.sprintf("F_BEND%d", C))
  sta ch_bend_lo+C
  sta ch_bend_hi+C
    .endif
    .if .ident(.sprintf("F_VIB%d", C))
  sta ch_vibphase+C
    .endif
    .if .ident(.sprintf("F_ARP%d", C))
  sta ch_arpstep+C
    .endif
    .if .ident(.sprintf("F_ARPENV%d", C))
  lda inst_arp_hi,x    ; no pitch envelope: mark it finished
  beq noenv
  lda #0
  .byte $2C            ; skip the next instruction
noenv:
  lda #$FF
  sta ch_arppos+C
    .endif
  lda inst_events,x
  .endif
  ora music_events
  sta music_events
done:
  lda ch_dur+C
  sta ch_wait+C
  tya
  clc
  adc ch_ptr+2*C
  sta ch_ptr+2*C
  bcc skip
  inc ch_ptr+2*C+1
skip:
.endmacro

; ===========================================================================
; Per-channel update: envelopes, arpeggio, portamento, bend, vibrato, detune, register writes.
; C = 0, 1 pulses, 2 triangle, 3 noise. Leaves m_t0 = duty/volume byte, m_t1 = final volume.
.macro UPDATE_CH C
  .local adv, noadv, ev, noenv, arpval, arpend, noarp, addarp, slide, slup, sldn, snap, slupgo
  .local sldone, slided, nobend, novib, nodet, sameh, trioff, arpstep1, noslide, done
  ldy ch_inst+C
  lda inst_env_lo,y
  sta m_ptr
  lda inst_env_hi,y
  sta m_ptr+1
  ; envelope clock: m_t1 = 1 if the envelopes advance this frame
.if .ident(.sprintf("F_RATE%d", C))
  lda #1
  ldx inst_rate,y
  beq adv
  dec ch_ratecnt+C
  bpl noadv
  stx ch_ratecnt+C
  .byte $2C            ; skip the next instruction
noadv:
  lda #0
adv:
  sta m_t1
.endif
  ; volume/duty envelope: bytes are duty << 6 | volume, or $10 + target = jump
  ldy ch_envpos+C
  lda (m_ptr),y
  sta m_t0
  and #$10
  beq ev
  iny
  lda (m_ptr),y
  tay
  lda (m_ptr),y
  sta m_t0
ev:
.if .ident(.sprintf("F_RATE%d", C))
  tya
  clc
  adc m_t1
  sta ch_envpos+C
.else
  iny
  sty ch_envpos+C
.endif
  ; pitch envelope: offsets -64..63, $80 + target = jump, $81 = finished
  lda ch_note+C
  sta m_lo
.if .ident(.sprintf("F_ARPENV%d", C))
  ldx ch_arppos+C
  bmi noenv
  ldy ch_inst+C
  lda inst_arp_lo,y
  sta m_ptr
  lda inst_arp_hi,y
  sta m_ptr+1
  txa
  tay
  lda (m_ptr),y
  bpl arpval
  cmp #$C0
  bcs arpval
  lsr
  bcs arpend
  iny
  lda (m_ptr),y
  tay
  lda (m_ptr),y
arpval:
  clc
  adc m_lo
  sta m_lo
  .if .ident(.sprintf("F_RATE%d", C))
  tya
  clc
  adc m_t1
  sta ch_arppos+C
  .else
  iny
  sty ch_arppos+C
  .endif
  jmp noenv
arpend:
  lda #$FF
  sta ch_arppos+C
noenv:
.endif
.if .ident(.sprintf("F_ARP%d", C))
  ; tracker arpeggio {arp xy}: note, +x, +y on successive frames
  lda ch_arp+C
  beq noarp
  ldy ch_arpstep+C     ; step 0 (the note), 1 (+x), 2 (+y), counted from the note-on
  iny
  cpy #3
  bcc :+
  ldy #0
: sty ch_arpstep+C     ; next frame's step
  dey                  ; this frame's: 0, 1 or $FF (= 2)
  beq noarp
  bpl arpstep1
  and #$0F             ; +y
  bpl addarp
arpstep1:
  lsr                  ; +x
  lsr
  lsr
  lsr
addarp:
  clc
  adc m_lo
  sta m_lo
noarp:
.endif
.if C = 3
  ; noise: m_lo is the period index
  lda m_t0
  and #$0F
  ora ch_vol+3
  tay
  lda voltab,y
  ora #$30
  sta $400C
  lda m_lo
  and #$0F
  ldy ch_inst+3
  ora inst_flags,y     ; bit 7: short (metallic) noise mode
  sta $400E
.else
  ; note -> period, with portamento while {slide} is non-zero
  ldy m_lo
  .if .ident(.sprintf("F_SLIDE%d", C))
  lda ch_slide+C
  beq noslide
  jmp slide
noslide:
  lda ptab_lo,y
  sta ch_cur_lo+C
  sta m_lo
  lda ptab_hi,y
  sta ch_cur_hi+C
  sta m_hi
  .else
  lda ptab_lo,y
  sta m_lo
  lda ptab_hi,y
  sta m_hi
  .endif
slided:
  .if .ident(.sprintf("F_BEND%d", C))
  ; pitch bend: accumulates from note-on while {bend} is non-zero
  lda ch_bendspd+C
  beq nobend
  ldy #0
  ora #0
  bpl :+
  dey
: clc
  adc ch_bend_lo+C
  sta ch_bend_lo+C
  tya
  adc ch_bend_hi+C
  sta ch_bend_hi+C
  lda m_lo
  clc
  adc ch_bend_lo+C
  sta m_lo
  lda m_hi
  adc ch_bend_hi+C
  sta m_hi
nobend:
  .endif
  .if .ident(.sprintf("F_VIB%d", C))
  ; delayed vibrato
  ldy ch_inst+C
  lda inst_vibdepth,y
  beq novib
  sta m_t1
  lda ch_vibdelay+C
  beq :+
  dec ch_vibdelay+C
  jmp novib
: lda ch_vibphase+C
  clc
  adc inst_vibspeed,y
  sta ch_vibphase+C
  lsr
  lsr
  lsr
  lsr
  ora m_t1             ; depth << 4 | phase >> 4
  tay
  lda vibtab,y
  ldx m_hi             ; above ~880 Hz (period < 128) halve it: depth is in period units
  bne :+
  ldx m_lo
  bmi :+
  cmp #$80
  ror
: jsr add_signed
novib:
  .endif
  .if .ident(.sprintf("F_DETUNE%d", C))
  lda ch_detune+C
  beq nodet
  jsr add_signed
nodet:
  .endif
  .if C = 2
  ; triangle: the envelope only gates it
  lda m_t0
  and #$0F
  beq trioff
  lda #$FF
  .byte $2C            ; skip the next instruction
trioff:
  lda #$80
  sta $4008
  lda m_lo
  sta $400A
  lda m_hi
  cmp ch_lasthi+2
  beq sameh
  sta ch_lasthi+2
  sta $400B
sameh:
  .else
  lda m_t0
  and #$0F
  ora ch_vol+C
  tay
  lda voltab,y
  sta m_t1             ; final volume (echo_store reads it for pulse 1)
  lda m_t0
  and #$C0
  ora m_t1
  ora #$30
  sta $4000+4*C
  lda m_lo
  sta $4002+4*C
  lda m_hi
  cmp ch_lasthi+C
  beq sameh            ; rewriting the high byte would reset the pulse's phase on hardware
  sta ch_lasthi+C
  sta $4003+4*C
sameh:
  .endif
  .if .ident(.sprintf("F_SLIDE%d", C))
  jmp done
slide:
  sta m_t1             ; speed
  lda ch_cur_lo+C
  sec
  sbc ptab_lo,y
  sta m_lo
  lda ch_cur_hi+C
  sbc ptab_hi,y
  bcc slup             ; current < target: the period rises
  bne sldn
  lda m_lo
  cmp m_t1
  bcc snap
sldn:
  lda ch_cur_lo+C
  sec
  sbc m_t1
  sta ch_cur_lo+C
  bcs sldone
  dec ch_cur_hi+C
  jmp sldone
slup:
  cmp #$FF
  bne slupgo
  lda m_lo
  clc
  adc m_t1
  bcc slupgo
snap:
  lda ptab_lo,y
  sta ch_cur_lo+C
  lda ptab_hi,y
  sta ch_cur_hi+C
  jmp sldone
slupgo:
  lda ch_cur_lo+C
  clc
  adc m_t1
  sta ch_cur_lo+C
  bcc sldone
  inc ch_cur_hi+C
sldone:
  lda ch_cur_lo+C
  sta m_lo
  lda ch_cur_hi+C
  sta m_hi
  jmp slided
  .endif
done:
.endif
.endmacro

; ===========================================================================
music_init:            ; A = song number. Call with NMI disabled or before enabling music_play.
  cmp #SONG_COUNT
  bcc :+
  lda #0
: pha
  ldx #0
  txa
: sta music_songframe,x  ; clear all of the driver's RAM
  inx
  bne :-
  pla
  tay
  lda song_ord_start,y
  sta m_ordstart
  lda song_ord_end,y
  sta m_ordend
  lda song_loop,y
  sta m_loopto
  lda song_rows,y
  sta m_rows
  lda song_speed0,y
  sta m_speed
  lda song_speed1,y
  sta m_speed+1
  lda song_speed2,y
  sta m_speed+2
  lda song_speed3,y
  sta m_speed+3
  lda song_inst_base,y
  sta m_instbase
  lda #0
  sta music_order
  sta music_row
  sta music_events
  sta music_cue
  lda #$FF
  sta music_frame
  sta music_frame+1
  sta music_songframe
  sta music_songframe+1
  ldx #3
: lda #$FF
  sta ch_lasthi,x
  sta ch_arppos,x
  lda #$F0
  sta ch_vol,x
  lda m_instbase       ; each song's instrument 0 is silent
  sta ch_inst,x
  dex
  bpl :-
  ; APU
  lda #$40
  sta $4017            ; 4-step sequence, frame IRQ off
  lda #$0F
  sta $4015
  lda #$30
  sta $4000
  sta $4004
  sta $400C
  lda #$08             ; negate flag set so low notes are not muted by the sweep unit
  sta $4001
  sta $4005
  lda #$80
  sta $4008
  lda #$00
  sta $4010
  lda #DPCM_REST       ; the DMC level every sample starts and ends at
  sta $4011
  lda #$00
  sta $4003
  sta $4007
  sta $400B
  sta $400F
  lda m_ordstart
  sta m_ordabs
  jsr load_order
  lda #1
  sta m_playing
  rts

; ===========================================================================
music_stop:
  lda #0
  sta m_playing
  sta $4015
  lda #$30
  sta $4000
  sta $4004
  sta $400C
  lda #$80
  sta $4008
  rts

; ===========================================================================
music_play:            ; call exactly once per frame, from NMI, after time-critical PPU work
  lda m_playing
  bne :+
  rts
: inc music_frame
  bne :+
  inc music_frame+1
: inc music_songframe
  bne :+
  inc music_songframe+1
: lda #0
  sta music_events

  dec m_tick
  bmi :+
  jmp @norow
:
  ; ---- a new row
  lda m_started
  bne @nextrow
  inc m_started        ; first call: music_init loaded the first order
  lda #$03
  sta music_events
  bne @rowok
@nextrow:
  inc music_row
  lda music_row
  cmp m_rows
  bcc @row
  ; new pattern: its pointers were loaded on the previous frame
  lda #0
  sta music_row
  lda m_nextabs
  sta m_ordabs
  sec
  sbc m_ordstart
  sta music_order
  lda #$03
  ldy m_looped
  beq :+
  lda #0
  sta music_songframe
  sta music_songframe+1
  lda #$83
: sta music_events
  jmp @rowok
@row:
  lda #$01
  sta music_events
@rowok:
  lda music_row        ; row length from the 4-step groove
  and #3
  tay
  ldx m_speed,y
  dex
  stx m_tick
  jmp parse_all
@norow:
  lda m_tick
  ; on the last frame of a pattern, point the channels at the next one (rows are only read on
  ; row frames, so this is inaudible, and it keeps the pattern-start frame cheaper)
  bne @upd
  ldy music_row
  iny
  cpy m_rows
  bcs :+
@upd:
  jmp update_all
:
  ldy m_ordabs
  iny
  lda #0
  cpy m_ordend
  bcc :+
  ldy m_loopto
  lda #1
: sta m_looped
  tya
  jsr load_order
  jmp update_all

parse_all:
  PARSE_CH 0
  PARSE_CH 1
  PARSE_CH 2
  PARSE_CH 3
  PARSE_CH 4
update_all:
  UPDATE_CH 0
  ; echo history: remember pulse 1's output (m_t0 duty, m_t1 volume, m_hi:m_lo period)
  ldx m_echopos
  inx
  txa
  and #63
  sta m_echopos
  tay
  ldx m_hi
  lda hi_shl4,x
  ora m_t1
  sta m_t1
  lda m_t0
  and #$C0
  ora m_t1
  sta echo_a,y
  lda m_lo
  sta echo_b,y
  lda m_echolevel
  beq :+
  jsr echo_play
  jmp update_tn
: UPDATE_CH 1
update_tn:
  UPDATE_CH 2
  UPDATE_CH 3
  ; DMC retrigger (rolls and stutters): restart the last sample every m_retrig frames
  lda m_retrig
  beq @nort
  dec m_retrigcnt
  bne @nort
  sta m_retrigcnt
  ldx m_lastsmp
  lda #$0F
  sta $4015
  lda smp_rate,x
  sta $4010
  lda smp_addr,x
  sta $4012
  lda smp_len,x
  sta $4013
  lda #$1F
  sta $4015
  lda smp_events,x
  ora music_events
  sta music_events
@nort:
  rts

; ---------------------------------------------------------------------------
; A = absolute order index: point every channel at its pattern for that order.
load_order:
  sta m_nextabs
  tay
  lda ord_tr,y
  sta m_transpose
  .repeat 5, C
    ldx .ident(.sprintf("ord_ch%d", C)),y
    lda pat_lo,x
    sta ch_ptr+2*C
    lda pat_hi,x
    sta ch_ptr+2*C+1
  .endrepeat
  lda #0
  ldx #4
: sta ch_wait,x
  dex
  bpl :-
  rts

; ---------------------------------------------------------------------------
; Effect command for channel X: A = $E0+n, (m_ptr),y = argument. Advances Y.
do_fx:
  and #$1F
  sta m_t0
  lda (m_ptr),y
  iny
  sty m_t1
  ldy m_t0
  beq @arp
  dey
  beq @slide
  dey
  beq @bend
  dey
  beq @vol
  dey
  beq @detune
  ; $E5: echo, three argument bytes: delay, flags (bit0 octave up), level << 4 (0 = off)
  sta m_echodelay
  ldy m_t1
  lda (m_ptr),y
  sta m_echoflags
  iny
  lda (m_ptr),y
  sta m_echolevel
  iny
  rts
@arp:
  sta ch_arp,x
  ldy m_t1
  rts
@slide:
  sta ch_slide,x
  ldy m_t1
  rts
@bend:
  sta ch_bendspd,x
  ldy m_t1
  rts
@vol:
  sta ch_vol,x
  ldy m_t1
  rts
@detune:
  sta ch_detune,x
  ldy m_t1
  rts

; m_hi:m_lo += sign-extended A
add_signed:
  ldy #0
  ora #0
  bpl :+
  dey
: clc
  adc m_lo
  sta m_lo
  tya
  adc m_hi
  sta m_hi
  rts

; ---------------------------------------------------------------------------
hi_shl4: .byte $00, $10, $20, $30, $00, $10, $20, $30   ; (period hi & 3) << 4

; Pulse 2 replays pulse 1 from m_echodelay frames ago at m_echolevel, optionally an octave up,
; plus pulse 2's {detune}.
echo_play:
  lda m_echopos
  sec
  sbc m_echodelay
  and #63
  tay
  lda echo_b,y
  sta m_lo
  lda echo_a,y
  sta m_t0
  lsr
  lsr
  lsr
  lsr
  and #3
  sta m_hi
  lda m_echoflags
  lsr
  bcc :+
  lsr m_hi
  ror m_lo
: lda ch_detune+1
  beq :+
  jsr add_signed
: lda m_t0
  and #$0F
  ora m_echolevel
  tay
  lda voltab,y
  sta m_t1
  lda m_t0
  and #$C0
  ora m_t1
  ora #$30
  sta $4004
  lda m_lo
  sta $4006
  lda m_hi
  cmp ch_lasthi+1
  beq :+
  sta ch_lasthi+1
  sta $4007
: rts

; voltab[(c << 4) | e] = round(c * e / 15), at least 1 when both are non-zero
voltab:
  .repeat 16, C
    .repeat 16, E
      .if C * E = 0
        .byte 0
      .elseif (C * E * 2 + 15) / 30 < 1
        .byte 1
      .else
        .byte (C * E * 2 + 15) / 30
      .endif
    .endrepeat
  .endrepeat

.segment "DPCM"
.include "dpcm.inc"
